using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
namespace RcsMap {
 public static class TerrainDriveTests {
  static int count;
  static void Check(bool value,string name){if(!value)throw new Exception("terrain drive: "+name);count++;}
  static void Throws(Action action,string name){bool caught=false;try{action();}catch{caught=true;}Check(caught,name);}
  public static MapDocument Demo(bool bound){var d=ContinuousTests.Demo();d.Version=6;d.TerrainDrive=new TerrainDriveSettings();if(bound){d.TerrainDrive.BrakeValidated=true;d.TerrainDrive.BrakeFunction="test_terrain_brake";}return d;}
  public static MapDocument Multi(){var d=Demo(true);var deck=d.Terrain.Surfaces[1];d.Points.Insert(1,new Waypoint(4000,2500,0,100){SurfaceId=deck.Id});d.Points.Insert(2,new Waypoint(4000,2800,0,100){SurfaceId=deck.Id});d.Points[3].Y=2800;d.Points[1].ArrivalActions.Add(new RouteAction{Kind=2,Value=90,Name="平台旋转90"});d.Points[2].ArrivalActions.Add(new RouteAction{Kind=1,Value=0,Name="下坡前转向"});return d;}
  public static void Write(string folder){Directory.CreateDirectory(folder);for(int layout=0;layout<3;layout++){var d=Demo(true);d.Settings.Layout=layout;File.WriteAllText(Path.Combine(folder,"terrain-layout"+layout+".json"),d.Json(),new UTF8Encoding(false));}File.WriteAllText(Path.Combine(folder,"terrain-multi.json"),Multi().Json(),new UTF8Encoding(false));File.WriteAllText(Path.Combine(folder,"terrain-demo.rcsmap.json"),Demo(false).Json(),new UTF8Encoding(false));}
  public static void Run(string folder){Directory.CreateDirectory(folder);var d=Demo(false);string source=d.Json();var files=Exporter.Generate(d);Check(files.Count==21,"nonflat emits4C4H");Check(files.ContainsKey("rcs_terrain.c")&&files.ContainsKey("rcs_terrain.h"),"real terrain C/H");Check(files["rcs_nav.h"].Contains("#include \"rcs_terrain.h\""),"optional declaration for project helper");Check(files["rcs_nav.h"].Contains("int rcs_nav_bind_terrain"),"public terrain bind API");Check(files["rcs_route.c"].Contains("return rcs_nav_bind_terrain"),"route binds execution notstub");Check(files["rcs_nav.c"].Contains("rcs_terrain_integrate(&n->terrain"),"one projected odometry path");Check(files["rcs_terrain.c"].Contains("along * dt_s"),"wheel surface delta is not divided bycos");Check(d.Points.Count==2&&d.Json()==source,"export doesn't insert task nodes ormutatemap");Check(d.Points.All(p=>!CorrectionRules.Items(p).Any()),"no independent correction injected");Check(files["rcs_actions.c"].Contains("RCS_TERRAIN_BRAKE")&&files["rcs_actions.c"].Contains("return 0;"),"unbound braking honestly unavailable");foreach(var f in files)UserRegions.Check(f.Value);Check(true,"all17modules sealed");
   Check(Exporter.Generate(MapDocument.Demo()).Count==19,"flat15files");var copy=d.Clone();copy.Points[0].Yaw=90;Throws(()=>Exporter.Generate(copy),"misaligned plannedentryheading rejected");copy.Points[0].DepartureActions.Add(new RouteAction{Kind=1,Value=0});Check(Exporter.Generate(copy).Count==21,"visibleflatrotation resolvesentryheading");copy=d.Clone();copy.Points[1].Y+=200;Throws(()=>Exporter.Generate(copy),"crossslope travel rejected");copy=TerrainGeometry.Demo();Throws(()=>Exporter.Generate(copy),"taskstoponramp unsupported");copy=d.Clone();copy.Points[0].X=1450;Throws(()=>Exporter.Generate(copy),"taskfootprintmustbeflatbeforeentry");copy=d.Clone();copy.TerrainDrive.LateralToleranceMm=Double.NaN;Throws(()=>copy.StructuralCheck(),"nonfinitecalibration rejected");copy=d.Clone();copy.TerrainDrive.BrakeValidated=true;Throws(()=>copy.StructuralCheck(),"brakeverificationneedsrealbinding");copy=d.Clone();copy.TerrainDrive.BrakeHeader="../foreign.h";Throws(()=>copy.StructuralCheck(),"brakeheadertraversal rejected");copy=d.Clone();copy.TerrainDrive.BrakeFunction="a(); evil";Throws(()=>copy.StructuralCheck(),"brakecallback injection rejected");
   copy=d.Clone();var ramp=copy.Terrain.Surfaces[0];SurfaceOutline.ApplyPreset(ramp,"trapezoid");Check(Exporter.Generate(copy).Count==21,"reshapedramp usedbyexecutionexport");Check(copy.Clone().Version==6&&copy.Clone().Terrain.Surfaces[0].Outline!=null,"v6shapemotionroundtrip");
   string destination=Path.Combine(folder,"export");d=Demo(false);Exporter.Export(d,destination);string path=Path.Combine(destination,"rcs_actions.c");File.WriteAllText(path,File.ReadAllText(path).Replace("/* 可在此补充真实硬件检查；未返回时使用下方配置绑定。 */","/* 保留制动用户代码 */"),new UTF8Encoding(false));d.TerrainDrive.BrakeValidated=true;d.TerrainDrive.BrakeFunction="test_terrain_brake";Exporter.Export(d,destination);Check(File.ReadAllText(path).Contains("保留制动用户代码"),"brakeusercodepreserved");Check(File.ReadAllText(path).Contains("return test_terrain_brake(context, request);"),"unboundtoboundregenerationupdatesbinding");d.TerrainDrive.BrakeFunction="replacement_brake";Exporter.Export(d,destination);Check(File.ReadAllText(path).Contains("return replacement_brake(context, request);")&&!File.ReadAllText(path).Contains("return test_terrain_brake(context, request);"),"bindingchangeisnotfrozeninusercode");string before=File.ReadAllText(path);Exporter.Export(d,destination);Check(File.ReadAllText(path)==before,"terrainrepeatstable");
   Write(folder);File.WriteAllText(Path.Combine(folder,"terrain-drive-selftest.txt"),"PASS "+count+" terrain generation checks\n");Console.WriteLine("PASS "+count+" terrain generation checks");
  }
 }
}
